$message='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verifyCsrf((string)($_POST['csrf_token']??'')))$message='Sesi tidak valid.';elseif(isset($_POST['quiz_state'])){setQuizOpen($_POST['quiz_state']==='open');rotateCsrf();$message=$_POST['quiz_state']==='open'?'Sesi kuis dibuka.':'Sesi kuis ditutup.';}}
$perPage=15;
$pSearch=trim((string)($_GET['participant_q']??''));$pPage=max(1,(int)($_GET['participant_page']??1));$pWhere='';$pParams=[];if($pSearch!==''){$pWhere=' WHERE name LIKE ? OR whatsapp LIKE ? OR tiktok_account LIKE ? OR tiktok_profile_url LIKE ? OR token LIKE ? OR status LIKE ? OR risk_status LIKE ?';$like='%'.$pSearch.'%';$pParams=[$like,$like,$like,$like,$like,$like,$like];}$pCount=db()->prepare('SELECT COUNT(*) FROM participants'.$pWhere);$pCount->execute($pParams);$pTotal=(int)$pCount->fetchColumn();$pPages=max(1,(int)ceil($pTotal/$perPage));$pPage=min($pPage,$pPages);$pOffset=($pPage-1)*$perPage;$pSql="SELECT id,name,whatsapp,tiktok_account,tiktok_profile_url,token,status,correct_count,risk_status,risk_score,risk_reasons,submitted_at FROM participants{$pWhere} ORDER BY CASE WHEN risk_status='flagged' THEN 0 ELSE 1 END ASC, CASE WHEN status='pending' THEN 0 ELSE 1 END ASC, submitted_at ASC, id ASC LIMIT {$perPage} OFFSET {$pOffset}";$pStmt=db()->prepare($pSql);$pStmt->execute($pParams);$rows=$pStmt->fetchAll();
$rSearch=trim((string)($_GET['raffle_q']??''));$rPage=max(1,(int)($_GET['raffle_page']??1));$rWhere='';$rParams=[];if($rSearch!==''){$rWhere=' WHERE r.raffle_number LIKE ? OR p.name LIKE ? OR p.whatsapp LIKE ? OR p.tiktok_account LIKE ? OR p.token LIKE ?';$like='%'.$rSearch.'%';$rParams=[$like,$like,$like,$like,$like];}$rCount=db()->prepare('SELECT COUNT(*) FROM raffle_numbers r JOIN participants p ON p.id=r.participant_id'.$rWhere);$rCount->execute($rParams);$rTotal=(int)$rCount->fetchColumn();$rPages=max(1,(int)ceil($rTotal/$perPage));$rPage=min($rPage,$rPages);$rOffset=($rPage-1)*$perPage;$rSql="SELECT r.raffle_number,p.name,p.whatsapp,p.tiktok_account,p.token,p.correct_count,p.reviewed_at FROM raffle_numbers r JOIN participants p ON p.id=r.participant_id{$rWhere} ORDER BY r.id ASC LIMIT {$perPage} OFFSET {$rOffset}";$rStmt=db()->prepare($rSql);$rStmt->execute($rParams);$raffles=$rStmt->fetchAll();$open=quizIsOpen();

$trafficSchedule=quizScheduleSettings();$trafficStartDate=$trafficSchedule['start_at']!==''?DateTimeImmutable::createFromFormat('Y-m-d H:i:s',$trafficSchedule['start_at']):false;$trafficEndDate=$trafficSchedule['end_at']!==''?DateTimeImmutable::createFromFormat('Y-m-d H:i:s',$trafficSchedule['end_at']):false;if($trafficStartDate&&$trafficEndDate&&$trafficEndDate>=$trafficStartDate){$trafficStart=$trafficStartDate->setTime(0,0);$trafficEnd=$trafficEndDate->setTime(0,0);$trafficDays=(int)$trafficStart->diff($trafficEnd)->days+1;}else{$trafficDays=14;$trafficEnd=new DateTimeImmutable('today');$trafficStart=$trafficEnd->modify('-'.($trafficDays-1).' days');}$trafficStmt=db()->prepare('SELECT DATE(submitted_at) traffic_date, COUNT(*) total FROM participants WHERE submitted_at >= ? AND submitted_at < ? GROUP BY DATE(submitted_at) ORDER BY traffic_date');$trafficStmt->execute([$trafficStart->format('Y-m-d 00:00:00'),$trafficEnd->modify('+1 day')->format('Y-m-d 00:00:00')]);$trafficByDate=[];foreach($trafficStmt->fetchAll() as $trafficRow){$trafficByDate[(string)$trafficRow['traffic_date']]=(int)$trafficRow['total'];}
$trafficLabels=[];$trafficValues=[];for($dayIndex=0;$dayIndex<$trafficDays;$dayIndex++){$day=$trafficStart->modify('+'.$dayIndex.' days');$dateKey=$day->format('Y-m-d');$trafficLabels[]=$day->format('d/m');$trafficValues[]=$trafficByDate[$dateKey]??0;}
$trafficQuota=dailyParticipantQuota();$trafficToday=$trafficByDate[(new DateTimeImmutable('today'))->format('Y-m-d')]??0;$trafficUsedPercent=min(100,round(($trafficToday/$trafficQuota)*100,1));$hoursElapsed=max(1/60,(time()-(new DateTimeImmutable('today'))->getTimestamp())/3600);$trafficPerHour=round($trafficToday/$hoursElapsed,1);$trafficEtaHours=$trafficPerHour>0?max(0,($trafficQuota-$trafficToday)/$trafficPerHour):null;
function whatsappChatUrl(string $number):string{return 'https://wa.me/'.preg_replace('/\D+/','',$number);}function pageLinks(int $current,int $pages,string $key):void{if($pages<=1)return;echo '<nav class="pagination">';if($current>1)echo '<a href="'.e(paginationUrl([$key=>$current-1])).'">ï¿½ Sebelumnya</a>';echo '<span>Halaman '.$current.' dari '.$pages.'</span>';if($current<$pages)echo '<a href="'.e(paginationUrl([$key=>$current+1])).'">Berikutnya ï¿½</a>';echo '</nav>';}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Kuis Affan Elektronik</title><link rel="icon" type="image/png" href="../assets/favicon.png"><link rel="shortcut icon" href="../assets/favicon.ico"><link rel="stylesheet" href="../assets/style.css"></head><body><div class="container wide"><div class="card"><div class="admin-brand"><img src="../assets/affan-logo.png" alt="Affan Elektronik"><span>Panel Kuis Affan Elektronik</span></div><div class="topbar"><h1>Data Peserta</h1><div><a class="small-button" href="export.php">Export Excel Nomor Undian</a> <a class="small-button" href="configuration.php">Konfigurasi</a> <a class="small-button" href="password.php">Ganti Password</a> <a href="logout.php">Logout</a></div></div><?php if($message):?><div class="success-alert"><?=e($message)?></div><?php endif;?><div class="session-box"><div><strong>Status kuis:</strong> <span class="status-badge <?=$open?'open':'closed'?>"><?=$open?'DIBUKA':'DITUTUP'?></span></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="quiz_state" value="<?=$open?'closed':'open'?>"><button type="submit" class="<?=$open?'danger-button':''?>"><?=$open?'Tutup Sesi Kuis':'Buka Sesi Kuis'?></button></form></div>
<section class="traffic-panel" aria-labelledby="traffic-title"><div class="traffic-heading"><div><h2 id="traffic-title">Trafik Submit Peserta</h2><p class="muted">Perbandingan jumlah submit dengan kuota harian selama periode kuis (<span id="trafficDays"><?=$trafficDays?></span> hari).</p><small class="traffic-update-status" id="trafficUpdateStatus">Diperbarui otomatis setiap 30 detik.</small></div><div class="traffic-legend"><span><i class="traffic-dot participant"></i> Submit</span><span><i class="traffic-dot quota"></i> Kuota</span></div></div><div class="traffic-stats"><div><span>Submit hari ini</span><strong id="trafficToday"><?=number_format($trafficToday,0,',','.')?></strong></div><div><span>Kuota terpakai</span><strong id="trafficUsedPercent"><?=number_format($trafficUsedPercent,1,',','.')?>%</strong></div><div><span>Kecepatan hari ini</span><strong id="trafficPerHour"><?=number_format($trafficPerHour,1,',','.')?>/jam</strong></div><div><span>Perkiraan kuota habis</span><strong id="trafficEta"><?php if($trafficToday >= $trafficQuota):?>Sudah habis<?php elseif($trafficEtaHours===null):?>Belum dapat dihitung<?php elseif($trafficEtaHours>=24):?>Lebih dari 24 jam<?php else:?><?=number_format($trafficEtaHours,1,',','.')?> jam lagi<?php endif;?></strong></div></div><div class="traffic-chart-wrap"><canvas id="trafficChart" width="1100" height="350" role="img" aria-label="Grafik trafik submit peserta selama periode kuis"></canvas></div></section>
<div class="topbar section-heading"><div><h2>Daftar Peserta</h2><p class="muted">Data berisiko dan belum direview ditampilkan paling atas.</p></div><form method="get" class="table-search server-search"><label for="participant_q">Cari peserta</label><div class="search-row"><input type="search" id="participant_q" name="participant_q" value="<?=e($pSearch)?>" placeholder="Nama, WA, token, status..."><input type="hidden" name="raffle_q" value="<?=e($rSearch)?>"><button type="submit" class="small-button">Cari</button><?php if($pSearch!==''):?><a class="small-button secondary-button" href="<?=e(paginationUrl(['participant_q'=>null,'participant_page'=>null]))?>">Reset</a><?php endif;?></div></form></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>WhatsApp</th><th>Akun / Username TikTok</th><th>Link Profile</th><th>Token</th><th>Status</th><th>Risiko</th><th>Benar</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><a href="<?=e(whatsappChatUrl((string)$r['whatsapp']))?>" target="_blank" rel="noopener noreferrer"><?=e($r['whatsapp'])?></a></td><td><?=e((string)$r['tiktok_account'])?></td><td><a href="<?=e((string)$r['tiktok_profile_url'])?>" target="_blank" rel="noopener noreferrer">Buka Profile</a></td><td><?=e($r['token'])?></td><td><?=e($r['status'])?></td><td><?php if((string)$r['risk_status']==='flagged'):?><span class="status-badge closed" title="<?=e((string)$r['risk_reasons'])?>">Perlu perhatian (<?= (int)$r['risk_score']?>)</span><?php else:?><span class="status-badge open">Normal</span><?php endif;?></td><td><?=(int)$r['correct_count']?></td><td><?=e($r['submitted_at'])?></td><td><a class="small-button" href="review.php?id=<?=(int)$r['id']?>">Koreksi</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="10">Data peserta tidak ditemukan.</td></tr><?php endif;?></tbody></table></div><div class="table-footer"><span>Menampilkan <?=count($rows)?> dari <?=$pTotal?> peserta</span><?php pageLinks($pPage,$pPages,'participant_page');?></div>
<div class="topbar section-heading"><div><h2>Daftar Nomor Undian</h2><p class="muted">Nomor urut unik beserta pemiliknya.</p></div><div class="table-actions"><form method="get" class="table-search server-search"><label for="raffle_q">Cari nomor undian</label><div class="search-row"><input type="search" id="raffle_q" name="raffle_q" value="<?=e($rSearch)?>" placeholder="Nomor, nama, WA, token..."><input type="hidden" name="participant_q" value="<?=e($pSearch)?>"><button type="submit" class="small-button">Cari</button><?php if($rSearch!==''):?><a class="small-button secondary-button" href="<?=e(paginationUrl(['raffle_q'=>null,'raffle_page'=>null]))?>">Reset</a><?php endif;?></div></form></div></div><div class="table-wrap"><table><thead><tr><th>No.</th><th>Nomor Undian</th><th>Nama Pemilik</th><th>Nomor WhatsApp</th><th>Akun / Username TikTok</th><th>Token</th><th>Total Benar</th><th>Tanggal Koreksi</th></tr></thead><tbody><?php foreach($raffles as $i=>$r):?><tr><td><?=$rOffset+$i+1?></td><td><strong><?=e($r['raffle_number'])?></strong></td><td><?=e($r['name'])?></td><td><a href="<?=e(whatsappChatUrl((string)$r['whatsapp']))?>" target="_blank" rel="noopener noreferrer"><?=e($r['whatsapp'])?></a></td><td><?=e((string)$r['tiktok_account'])?></td><td><?=e($r['token'])?></td><td><?=(int)$r['correct_count']?></td><td><?=e((string)$r['reviewed_at'])?></td></tr><?php endforeach;?><?php if(!$raffles):?><tr><td colspan="8">Nomor undian tidak ditemukan.</td></tr><?php endif;?></tbody></table></div><div class="table-footer"><span>Menampilkan <?=count($raffles)?> dari <?=$rTotal?> nomor undian</span><?php pageLinks($rPage,$rPages,'raffle_page');?></div></div></div><script nonce="<?=cspNonce()?>">
(()=>{const canvas=document.getElementById('trafficChart');if(!canvas)return;let labels=<?=json_encode($trafficLabels,JSON_UNESCAPED_SLASHES)?>,values=<?=json_encode($trafficValues,JSON_UNESCAPED_SLASHES)?>,quota=<?=$trafficQuota?>;const ctx=canvas.getContext('2d'),status=document.getElementById('trafficUpdateStatus'),format=value=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(value);function draw(){const ratio=window.devicePixelRatio||1,w=canvas.clientWidth||1100,h=Math.max(260,Math.min(350,w*.36));canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,w,h);const pad={l:52,r:22,t:24,b:44},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b,max=Math.max(5,quota,...values),stepX=labels.length>1?cw/(labels.length-1):0,labelStep=Math.max(1,Math.ceil(labels.length/(w<650?7:14)));ctx.font='12px sans-serif';ctx.textBaseline='middle';for(let i=0;i<=4;i++){const y=pad.t+ch*i/4,val=Math.round(max*(1-i/4));ctx.strokeStyle='#e2e8f0';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillStyle='#64748b';ctx.textAlign='right';ctx.fillText(val,pad.l-9,y)}labels.forEach((label,i)=>{if(i%labelStep!==0&&i!==labels.length-1)return;ctx.fillStyle='#64748b';ctx.textAlign='center';ctx.fillText(label,pad.l+i*stepX,h-18)});function line(data,color,dashed){ctx.strokeStyle=color;ctx.lineWidth=3;ctx.lineJoin='round';ctx.lineCap='round';ctx.setLineDash(dashed?[7,6]:[]);ctx.beginPath();data.forEach((v,i)=>{const x=pad.l+i*stepX,y=pad.t+ch-(v/max)*ch;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.setLineDash([])}line(labels.map(()=>quota),'#f59e0b',true);line(values,'#2563eb',false);values.forEach((v,i)=>{const x=pad.l+i*stepX,y=pad.t+ch-(v/max)*ch;ctx.fillStyle='#fff';ctx.strokeStyle='#2563eb';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,3.5,0,Math.PI*2);ctx.fill();ctx.stroke()})}async function refresh(){try{const response=await fetch('traffic-data.php',{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)throw new Error('request failed');const data=await response.json();if(!data.ok)throw new Error('invalid data');labels=data.labels;values=data.values;quota=data.quota;document.getElementById('trafficDays').textContent=data.days;document.getElementById('trafficToday').textContent=format(data.today);document.getElementById('trafficUsedPercent').textContent=format(data.used_percent)+'%';document.getElementById('trafficPerHour').textContent=format(data.per_hour)+'/jam';document.getElementById('trafficEta').textContent=data.eta_label;status.textContent='Terakhir diperbarui pukul '+data.updated_at+' WIB · otomatis setiap 30 detik.';status.classList.remove('error');draw()}catch(error){status.textContent='Pembaruan otomatis gagal. Sistem akan mencoba kembali.';status.classList.add('error')}}draw();window.addEventListener('resize',draw);setInterval(refresh,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()})})();
</script></body></html>
